    /// cannot change what a later caller sees.
    pub fn instance_event_tag_registration(&self, region: &str) -> InstanceEventTagRegistration {
        self.instance_event_tag_registrations
            .get(region)
            .cloned()
            .unwrap_or_default()
    }

